CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username TEXT UNIQUE NOT NULL, full_name TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'sales', password_hash TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customers(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, legacy_id TEXT, name TEXT NOT NULL, document TEXT, phone TEXT, email TEXT, address TEXT, city TEXT, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS suppliers(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, legacy_id TEXT, name TEXT NOT NULL, contact TEXT, document TEXT, phone TEXT, email TEXT, address TEXT, city TEXT, state TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sellers(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, legacy_id TEXT UNIQUE, name TEXT NOT NULL, document TEXT, phone TEXT, address TEXT, city TEXT, state TEXT, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS doctors(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, legacy_id TEXT, name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS stores(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, legacy_id TEXT, name TEXT NOT NULL, phone TEXT, address TEXT, city TEXT, discount_percent NUMERIC NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS payment_methods(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, legacy_id TEXT, name TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS products(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, legacy_id TEXT UNIQUE, sku TEXT, name TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'Armações', brand TEXT, model TEXT, unit TEXT DEFAULT 'UN', color TEXT, size TEXT, lens_type TEXT, stock NUMERIC NOT NULL DEFAULT 0, minimum_stock NUMERIC NOT NULL DEFAULT 0, cost NUMERIC NOT NULL DEFAULT 0, price NUMERIC NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sales(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, number TEXT UNIQUE NOT NULL, customer_id BIGINT REFERENCES customers(id), store_id BIGINT REFERENCES stores(id), seller_id BIGINT REFERENCES sellers(id), seller_name TEXT, status TEXT NOT NULL DEFAULT 'confirmed', subtotal NUMERIC NOT NULL, discount NUMERIC NOT NULL DEFAULT 0, total NUMERIC NOT NULL, payment_method TEXT, notes TEXT, created_by BIGINT REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE sales ADD COLUMN IF NOT EXISTS seller_id BIGINT REFERENCES sellers(id);
CREATE TABLE IF NOT EXISTS sale_items(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sale_id BIGINT NOT NULL REFERENCES sales(id), product_id BIGINT NOT NULL REFERENCES products(id), product_name TEXT NOT NULL, quantity NUMERIC NOT NULL, unit_price NUMERIC NOT NULL, discount NUMERIC NOT NULL DEFAULT 0, total NUMERIC NOT NULL);
CREATE TABLE IF NOT EXISTS prescriptions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sale_id BIGINT NOT NULL UNIQUE REFERENCES sales(id), doctor_id BIGINT REFERENCES doctors(id), doctor_name TEXT, lens_description TEXT, addition TEXT, right_sphere TEXT, right_cylinder TEXT, right_axis TEXT, right_dnp TEXT, right_height TEXT, left_sphere TEXT, left_cylinder TEXT, left_axis TEXT, left_dnp TEXT, left_height TEXT, near_right_sphere TEXT, near_left_sphere TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS lab_orders(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sale_id BIGINT NOT NULL UNIQUE REFERENCES sales(id), status TEXT NOT NULL DEFAULT 'Pendente', estimated_date DATE, received_at TIMESTAMPTZ, started_at TIMESTAMPTZ, ready_at TIMESTAMPTZ, delivered_at TIMESTAMPTZ, notes TEXT);
CREATE TABLE IF NOT EXISTS receivables(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sale_id BIGINT NOT NULL REFERENCES sales(id), installment INTEGER NOT NULL, due_date DATE NOT NULL, amount NUMERIC NOT NULL, paid NUMERIC NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'Aberto', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS purchases(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, supplier_id BIGINT REFERENCES suppliers(id), description TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'confirmed', total NUMERIC NOT NULL, created_by BIGINT REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS purchase_items(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, purchase_id BIGINT NOT NULL REFERENCES purchases(id), product_id BIGINT NOT NULL REFERENCES products(id), product_name TEXT NOT NULL, quantity NUMERIC NOT NULL, unit_cost NUMERIC NOT NULL, total NUMERIC NOT NULL);
CREATE TABLE IF NOT EXISTS payables(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, purchase_id BIGINT REFERENCES purchases(id), supplier_id BIGINT REFERENCES suppliers(id), description TEXT NOT NULL, due_date DATE NOT NULL, amount NUMERIC NOT NULL, paid NUMERIC NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'Aberto', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE payables ADD COLUMN IF NOT EXISTS purchase_id BIGINT REFERENCES purchases(id);
CREATE TABLE IF NOT EXISTS cash_movements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, direction TEXT NOT NULL, category TEXT NOT NULL, description TEXT NOT NULL, amount NUMERIC NOT NULL, reference_type TEXT, reference_id BIGINT, created_by BIGINT REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS stock_movements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id BIGINT NOT NULL REFERENCES products(id), direction TEXT NOT NULL, quantity NUMERIC NOT NULL, reason TEXT NOT NULL, reference_type TEXT, reference_id BIGINT, created_by BIGINT REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT REFERENCES users(id), action TEXT NOT NULL, entity TEXT NOT NULL, entity_id TEXT, detail TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS legacy_sources(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, table_name TEXT NOT NULL UNIQUE, file_name TEXT NOT NULL, dbf_version INTEGER NOT NULL, record_count INTEGER NOT NULL, deleted_count INTEGER NOT NULL, fields JSONB NOT NULL, imported_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS legacy_rows(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, source_id BIGINT NOT NULL REFERENCES legacy_sources(id) ON DELETE CASCADE, row_number INTEGER NOT NULL, deleted BOOLEAN NOT NULL, payload JSONB NOT NULL, UNIQUE(source_id,row_number));
CREATE INDEX IF NOT EXISTS ix_products_name ON products(name); CREATE INDEX IF NOT EXISTS ix_sales_created ON sales(created_at); CREATE INDEX IF NOT EXISTS ix_receivables_due ON receivables(due_date,status); CREATE INDEX IF NOT EXISTS ix_lab_status ON lab_orders(status);
CREATE UNIQUE INDEX IF NOT EXISTS ux_customers_legacy ON customers(legacy_id); CREATE UNIQUE INDEX IF NOT EXISTS ux_suppliers_legacy ON suppliers(legacy_id); CREATE UNIQUE INDEX IF NOT EXISTS ux_doctors_legacy ON doctors(legacy_id); CREATE UNIQUE INDEX IF NOT EXISTS ux_stores_legacy ON stores(legacy_id); CREATE UNIQUE INDEX IF NOT EXISTS ux_payment_methods_legacy ON payment_methods(legacy_id);
